/* MIPS syscall wrapper - Linux o32 ABI: syscall number in $v0, args in $a0-$a2 */
static long syscall3(long n, long a, long b, long c)
{
    register long v0 asm("$2") = n;
    register long a0 asm("$4") = a;
    register long a1 asm("$5") = b;
    register long a2 asm("$6") = c;
    asm volatile (
        "syscall\n\t"
        : "+r"(v0)
        : "r"(a0), "r"(a1), "r"(a2)
        : "$7", "$8", "$9", "$10", "$11", "$12", "$13", "$14", "$15", "$24", "$25", "memory"
    );
    return v0;
}
static long syscall2(long n, long a, long b)
{
    return syscall3(n, a, b, 0);
}
static long syscall1(long n, long a)
{
    return syscall3(n, a, 0, 0);
}
static long syscall0(long n)
{
    return syscall3(n, 0, 0, 0);
}

