/* ---- memory allocator ---- */
static char heap_base[8 * 1024 * 1024];
static size_t heap_off = 0;
static char *heap_ptr = heap_base;

void *malloc(size_t size)
{
    size = (size + 7) & ~7UL;
    if (heap_off + size > sizeof(heap_base)) {
        return NULL;
    }
    void *p = heap_ptr + heap_off;
    heap_off += size;
    return p;
}

void *calloc(size_t nmemb, size_t size)
{
    size_t total = nmemb * size;
    void *p = malloc(total);
    if (p) memset(p, 0, total);
    return p;
}

void *realloc(void *p, size_t size)
{
    if (!p) return malloc(size);
    void *np = malloc(size);
    if (np) {
        size_t old = *(size_t *)((char *)p - 8);
        memcpy(np, p, old < size ? old : size);
    }
    return np;
}

