/* ---- ctype ---- */
static int ctype_table[256];
static int ctype_initialized = 0;
static int *ctype_toupper_ptr[256 + 128];

static void init_ctype(void)
{
    int i;
    for (i = 0; i < 256; i++) {
        ctype_table[i] = 0;
        if (i >= 'A' && i <= 'Z') ctype_table[i] |= 1;
        if (i >= 'a' && i <= 'z') ctype_table[i] |= 2;
        if (i >= '0' && i <= '9') ctype_table[i] |= 4;
        if ((i >= 'A' && i <= 'Z') || (i >= 'a' && i <= 'z') || (i >= '0' && i <= '9')) ctype_table[i] |= 8;
        if (i == ' ' || i == '\t' || i == '\n' || i == '\r' || i == 0x0b || i == 0x0c) ctype_table[i] |= 16;
        if (i >= 32 && i < 127) ctype_table[i] |= 32;
        if (i >= 33 && i <= 126) ctype_table[i] |= 64;
        if ((i >= 'a' && i <= 'f') || (i >= 'A' && i <= 'F') || (i >= '0' && i <= '9')) ctype_table[i] |= 128;
    }
    for (i = 0; i < 256 + 128; i++) {
        int c = i - 128;
        ctype_toupper_ptr[i] = (int *)(intptr_t)(c >= 'a' && c <= 'z' ? c - 32 : c);
    }
    ctype_initialized = 1;
}

const int32_t **__ctype_toupper_loc(void)
{
    if (!ctype_initialized) init_ctype();
    return (const int32_t **)ctype_toupper_ptr;
}

