/* ---- file I/O ---- */
FILE _stdin_file = {0};
FILE _stdout_file = {1};
FILE _stderr_file = {2};
FILE *stdin = &_stdin_file;
FILE *stdout = &_stdout_file;
FILE *stderr = &_stderr_file;

FILE *fopen(const char *path, const char *mode)
{
    int flags = 0;
    int access_mode = mode[0];
    if (access_mode == 'r') flags = 0;
    else if (access_mode == 'w') flags = 1 | 0100 | 01000;
    else if (access_mode == 'a') flags = 1 | 0100 | 02000;
    if (mode[1] == '+') {
        flags = 2;
        if (access_mode == 'w') flags |= 0100 | 01000;
        else if (access_mode == 'a') flags |= 0100 | 02000;
    }
    int fd = (int)syscall3(2, (long)path, flags, 0644);
    if (fd < 0) return NULL;
    FILE *fp = malloc(sizeof(FILE));
    if (!fp) { close(fd); return NULL; }
    fp->_fileno = fd;
    return fp;
}

int fclose(FILE *fp)
{
    if (!fp) return 0;
    if (fp == stdin || fp == stdout || fp == stderr) return 0;
    int r = close(fp->_fileno);
    free(fp);
    return r;
}

size_t fread(void *ptr, size_t size, size_t nmemb, FILE *fp)
{
    if (!fp) return 0;
    size_t total = size * nmemb;
    long r = syscall3(0, fp->_fileno, (long)ptr, total);
    return r > 0 ? (size_t)(r / size) : 0;
}

size_t fwrite(const void *ptr, size_t size, size_t nmemb, FILE *fp)
{
    if (!fp) return 0;
    size_t total = size * nmemb;
    long r = syscall3(1, fp->_fileno, (long)ptr, total);
    return r > 0 ? (size_t)(r / size) : 0;
}

int fseek(FILE *fp, long offset, int whence)
{
    if (!fp) return -1;
    long r = syscall3(8, fp->_fileno, offset, whence);
    return r < 0 ? -1 : 0;
