/* ---- printf family ---- */
static void out_char(char **buf, size_t *left, size_t cap, char c)
{
    if (buf) {
        if (*left > 0 || cap == 0) {
            if (cap == 0 || *left > 1) {
                **buf = c;
                (*buf)++;
            }
            if (*left > 0) (*left)--;
        }
    } else {
        write(1, &c, 1);
    }
}

static void out_str(char **buf, size_t *left, size_t cap, const char *s)
{
    if (!s) s = "(null)";
    while (*s) out_char(buf, left, cap, *s++);
}

static void out_uint(char **buf, size_t *left, size_t cap, unsigned long val, int base, int upper, int width, int pad_zero)
{
    char tmp[32];
    int i = 0;
    const char *digits = upper ? "0123456789ABCDEF" : "0123456789abcdef";
    if (val == 0) tmp[i++] = '0';
    while (val) { tmp[i++] = digits[val % base]; val /= base; }
    while (i < width && i < 32) tmp[i++] = pad_zero ? '0' : ' ';
    while (i > 0) out_char(buf, left, cap, tmp[--i]);
}

static void out_int(char **buf, size_t *left, size_t cap, long val, int base, int upper, int width, int pad_zero)
{
    if (val < 0) {
        out_char(buf, left, cap, '-');
        val = -val;
        if (width > 0) width--;
    }
    out_uint(buf, left, cap, (unsigned long)val, base, upper, width, pad_zero);
}

static int vformat(char *buf, size_t cap, const char *fmt, va_list ap)
{
    char *p = buf;
    size_t left = cap;
    while (*fmt) {
        if (*fmt != '%') {
            out_char(&p, &left, cap, *fmt++);
            continue;
        }
        fmt++;
        int pad_zero = 0, width = 0;
        if (*fmt == '0') { pad_zero = 1; fmt++; }
        while (*fmt >= '0' && *fmt <= '9') { width = width * 10 + (*fmt - '0'); fmt++; }
        /* skip length modifiers */
        while (*fmt == 'l' || *fmt == 'h' || *fmt == 'z' || *fmt == 'j') fmt++;
        switch (*fmt) {
            case 'd': case 'i': out_int(&p, &left, cap, va_arg(ap, int), 10, 0, width, pad_zero); break;
            case 'u': out_uint(&p, &left, cap, va_arg(ap, unsigned int), 10, 0, width, pad_zero); break;
            case 'x': out_uint(&p, &left, cap, va_arg(ap, unsigned int), 16, 0, width, pad_zero); break;
            case 'X': out_uint(&p, &left, cap, va_arg(ap, unsigned int), 16, 1, width, pad_zero); break;
            case 'c': out_char(&p, &left, cap, (char)va_arg(ap, int)); break;
            case 's': out_str(&p, &left, cap, va_arg(ap, const char *)); break;
            case 'p': out_char(&p, &left, cap, '0'); out_char(&p, &left, cap, 'x'); out_uint(&p, &left, cap, (unsigned long)va_arg(ap, void *), 16, 0, 0, 0); break;
            case 'f': {
                /* print integer part only for float */
                int v = (int)va_arg(ap, double);
                out_int(&p, &left, cap, v, 10, 0, width, pad_zero);
                out_char(&p, &left, cap, '.');
                out_char(&p, &left, cap, '0');
                break;
            }
            case '%': out_char(&p, &left, cap, '%'); break;
            default: out_char(&p, &left, cap, '%'); out_char(&p, &left, cap, *fmt); break;
        }
        if (*fmt) fmt++;
    }
    if (buf && cap > 0) {
        if (left > 0) *p = 0;
        else buf[cap - 1] = 0;
    }
    return buf ? (int)(p - buf) : 0;
}

int printf(const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    int r = vformat(NULL, 0, fmt, ap);
    va_end(ap);
    return r;
}

int fprintf(FILE *fp, const char *fmt, ...)
