int __isoc99_sscanf(const char *str, const char *fmt, ...)
{
    /* simplified sscanf for integers only */
    va_list ap;
    va_start(ap, fmt);
    int count = 0;
    while (*fmt) {
        if (*fmt == ' ' || *fmt == '\t') { while (*str == ' ' || *str == '\t') str++; fmt++; continue; }
        if (*fmt != '%') { if (*str != *fmt) break; str++; fmt++; continue; }
        fmt++;
        /* skip length modifiers */
        while (*fmt == 'l' || *fmt == 'h') fmt++;
        if (*fmt == 'x' || *fmt == 'X') {
            while (*str == ' ' || *str == '\t') str++;
            if (str[0] == '0' && (str[1] == 'x' || str[1] == 'X')) str += 2;
            unsigned int *p = va_arg(ap, unsigned int *);
            unsigned int val = 0;
            int got = 0;
            while (*str) {
                int d;
                if (*str >= '0' && *str <= '9') d = *str - '0';
                else if (*str >= 'a' && *str <= 'f') d = *str - 'a' + 10;
                else if (*str >= 'A' && *str <= 'F') d = *str - 'A' + 10;
                else break;
                val = val * 16 + d;
                str++; got = 1;
            }
            *p = val; if (got) count++;
            fmt++;
        } else if (*fmt == 'o') {
            while (*str == ' ' || *str == '\t') str++;
            unsigned int *p = va_arg(ap, unsigned int *);
            unsigned int val = 0;
            int got = 0;
            while (*str >= '0' && *str <= '7') { val = val * 8 + (*str - '0'); str++; got = 1; }
            *p = val; if (got) count++;
            fmt++;
        } else if (*fmt == 'd' || *fmt == 'i') {
            while (*str == ' ' || *str == '\t') str++;
            int sign = 1;
            if (*str == '-') { sign = -1; str++; }
            else if (*str == '+') str++;
